// Gate 7, source size: no hand-written package source file (packages/*/src and packages/shared: .ts, .js, .mjs,
// .wgsl) grows past LIMIT_BYTES. The files over it when the gate began (2026-11-28) are baselined at their size plus
// HEADROOM_BYTES, so a small bug fix still fits; more growth fails, and the fix is to move code out along a seam (one
// feature chunk, one pass, one solver per file) with the exports unchanged. Files a script writes (a first line
// `// Generated by`, or `.generated.` in the name: Wasm blueprints, exporter tables, umbrella re-exports) follow their
// generator and are left out. Sizes are UTF-8 bytes with LF line ends, so a Windows and a Mac checkout measure the same.
// Items: `<path>` -> bytes.
import { statSync } from 'node:fs';
import { join } from 'node:path';
import { readRepoFile } from './packages.js';

/** A package source file over this many bytes is an item. */
export const LIMIT_BYTES = 100 * 1024;
/** Room a baselined file earns over its measured size. */
export const HEADROOM_BYTES = 4 * 1024;

/** Whether `path` (repository-relative, / separators) is a package source file the gate measures. */
export const isSource = (path) =>
  /^packages\/([^/]+\/src|shared)\/.+\.(ts|js|mjs|wgsl)$/.test(path) &&
  !path.endsWith('.d.ts') &&
  !path.includes('.generated.') &&
  !path.includes('/node_modules/');

/** Whether a file's text says a script wrote it. */
export const isGenerated = (text) => /^\/\/ Generated by\b/.test(text);

/** Bytes of `text` as UTF-8 with LF line ends. */
export const sizeOf = (text) => Buffer.byteLength(text.replace(/\r\n/g, '\n'));

export function sourceSizeGate({ root, files }) {
  const items = {};
  for (const file of files) {
    if (!isSource(file)) continue;
    // A file no bigger than the limit on disk (CRLF only adds bytes) is under it, so only the bigger ones are read.
    let disk;
    try {
      disk = statSync(join(root, file)).size;
    } catch (error) {
      if (error?.code === 'ENOENT') continue; // removed since the listing
      throw error;
    }
    if (disk <= LIMIT_BYTES) continue;
    const text = readRepoFile(root, file, 'utf8');
    if (text === undefined || isGenerated(text)) continue;
    const bytes = sizeOf(text);
    if (bytes > LIMIT_BYTES) items[file] = bytes;
  }
  return {
    items,
    allowance: (value) => value + HEADROOM_BYTES,
    summary: () =>
      Object.entries(items)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 20)
        .map(([file, bytes]) => `  ${bytes} B  ${file}`),
  };
}
